DOMAIN5 = [{'num': 5, 'topic': 5, 'title': 'Separate path and server delay', 'objective': 'LO2', 'desc': 'Displayed delta depends on the current filter; capture delta does not.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Open data/branch-office.pcap. Apply tcp.stream == 1. Expand TCP in the final handshake ACK and inspect tcp.analysis.initial_rtt: 0.040 seconds. Separately measure SYN to SYN/ACK by setting a time reference on the SYN: 0.030 seconds.', ''), ('Locate GET /slow and its HTTP response. Set a new time reference on the request. Record the response delta: 0.760 seconds, including 0.010 seconds to the server ACK and 0.750 seconds thereafter.', ''), ('Apply http.request.uri == "/slow" || http.response.code == 200 and compare frame.time_delta with frame.time_delta_displayed on the filtered list. Explain why a displayed gap can span hidden packets.', ''), ('Write a hypothesis in outputs/findings.md: slow response with a synthetic 30 ms SYN-to-SYN/ACK interval and 40 ms complete handshake. Name a second observation point required to distinguish processing from a later path delay.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied http.request.uri == "/slow" || http.response.code == 200 expression matches 3 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 45}]
